import importlib,json,os,sys,traceback
result={'executable':sys.executable,'python_version':sys.version,'cwd':os.getcwd(),'imports':{},'gpu':{},'usable':False}
for name in ('torch','einx','einops','jaxtyping','cs336_basics.model'):
    try:
        module=importlib.import_module(name)
        if name=='cs336_basics.model':
            assert callable(module.BasicsTransformerLM)
        result['imports'][name]={'status':'ok','path':getattr(module,'__file__',None),'version':getattr(module,'__version__',None)}
    except Exception as exc:
        result['imports'][name]={'status':'error','error':repr(exc),'traceback':traceback.format_exc()}
if result['imports']['torch']['status']=='ok':
    import torch
    try:
        count=torch.cuda.device_count()
        result['gpu']={'cuda_available':torch.cuda.is_available(),'device_count':count,'devices':[torch.cuda.get_device_name(i) for i in range(count)],'nccl_available':torch.distributed.is_nccl_available(),'torch_cuda':torch.version.cuda,'nccl_version':torch.cuda.nccl.version() if torch.distributed.is_nccl_available() else None}
        result['usable']=all(result['imports'][name]['status']=='ok' for name in ('torch','einx','cs336_basics.model')) and result['gpu']['cuda_available'] and count>=2 and result['gpu']['nccl_available']
    except Exception as exc:
        result['gpu']={'error':repr(exc),'traceback':traceback.format_exc()}
print(json.dumps(result,ensure_ascii=False))
